(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"quadratic-form":{"h":"WHAT YOU ARE LOOKING AT","t":"For a matrix A and a vector x, the **quadratic form xᵀ A x** is one number. For **A = [[2, 0], [0, 1]]** it equals **2x₁² + x₂²**."},"directions":{"h":"TRY MANY DIRECTIONS","t":"Evaluate **xᵀ A x** for vectors pointing in many directions. Each arrow shows its value."},"positive-values":{"h":"EVERY DIRECTION GIVES A POSITIVE VALUE","t":"No matter which **non-zero direction** we pick, the value is above zero. That is what **positive definite** means."},"bowl":{"h":"POSITIVE VALUES MAKE A BOWL","t":"Plot the value as height and you get an **upward-curving bowl** with a single lowest point: a **stable minimum**."},"eigenvalues":{"h":"EQUIVALENT TEST: ALL EIGENVALUES POSITIVE","t":"A symmetric matrix is positive definite **exactly when all its eigenvalues are positive**. Here they are **2 and 1**."},"non-pd-contrast":{"h":"COMPARE WITH AN INDEFINITE MATRIX","t":"Take **B = [[1, 0], [0, −1]]**. Its value is positive along one axis but **negative along the other**, so the surface is a **saddle**."},"ml-connection":{"h":"TAKEAWAY","t":"Positive curvature means a loss has a **stable minimum**, and covariance matrices have this property. **Saddles are where optimization gets stuck.**"}};
  // ── scene ──
  var steps = [
    { id: "quadratic-form", label: "A number from a vector and a matrix", caption: "For a matrix A and a vector x, the quadratic form xᵀ A x is one number. For A = [[2, 0], [0, 1]] it equals 2x₁² + x₂²." },
    { id: "directions", label: "Try many directions", caption: "Evaluate xᵀ A x for vectors pointing in many directions. Each arrow shows its value." },
    { id: "positive-values", label: "Every direction gives a positive value", caption: "No matter which non-zero direction we pick, the value is above zero. That is what positive definite means." },
    { id: "bowl", label: "Positive values make a bowl", caption: "Plot the value as height and you get an upward-curving bowl with a single lowest point: a stable minimum." },
    { id: "eigenvalues", label: "Equivalent test: all eigenvalues are positive", caption: "A symmetric matrix is positive definite exactly when all its eigenvalues are positive. Here they are 2 and 1." },
    { id: "non-pd-contrast", label: "Compare with an indefinite matrix", caption: "Take B = [[1, 0], [0, −1]]. Its value is positive along one axis but negative along the other, so the surface is a saddle." },
    { id: "ml-connection", label: "Why this matters for ML", caption: "Positive curvature means a loss has a stable minimum, and covariance matrices have this property. Saddles are where optimization gets stuck." }
  ];

  var PL = makePlane(165, 190, 32); // left: positive definite
  var PR = makePlane(485, 190, 32); // right: saddle
  function qfA(x, y) { return 2 * x * x + y * y; }
  function qfB(x, y) { return x * x - y * y; }

  // Left panel axes + title.
  var left = el("g", {}, svg);
  axes(left, PL, 4.5, 4.5);
  txt(left, PL.cx, 34, "lbl lbl-g", "A = [[2, 0], [0, 1]]", "middle");
  var right = el("g", { opacity: 0 }, svg);
  axes(right, PR, 4.5, 4.5);
  txt(right, PR.cx, 34, "lbl lbl-r", "B = [[1, 0], [0, −1]]", "middle");

  // Contours: ellipses for A (bowl), hyperbolas for B (saddle).
  var contourA = el("g", { opacity: 0 }, left);
  [1, 2, 3.4].forEach(function (c) {
    el("ellipse", { cx: PL.cx, cy: PL.cy, rx: Math.sqrt(c / 2) * PL.s * 1.9, ry: Math.sqrt(c) * PL.s * 1.9, fill: "none", stroke: "#1db584", "stroke-width": 2 }, contourA);
  });
  var ball = el("circle", { cx: PL.cx, cy: PL.cy, r: 7, fill: "#e2b44a", opacity: 0 }, left);
  var ballLab = txt(left, PL.cx + 12, PL.cy + 30, "lbl lbl-y", "minimum", "start");
  show(ballLab, false);

  var contourB = el("g", { opacity: 0 }, right);
  [-1.2, 1.2].forEach(function (c) {
    // x² − y² = c, drawn as four branches
    var pts1 = [], pts2 = [];
    for (var t = -1.6; t <= 1.601; t += 0.1) {
      if (c > 0) {
        var x = Math.sqrt(c) * ((Math.exp(t) + Math.exp(-t)) / 2);
        var y = Math.sqrt(c) * ((Math.exp(t) - Math.exp(-t)) / 2);
        pts1.push(PR.x(x) + "," + PR.y(y));
        pts2.push(PR.x(-x) + "," + PR.y(y));
      } else {
        var y2 = Math.sqrt(-c) * ((Math.exp(t) + Math.exp(-t)) / 2);
        var x2 = Math.sqrt(-c) * ((Math.exp(t) - Math.exp(-t)) / 2);
        pts1.push(PR.x(x2) + "," + PR.y(y2));
        pts2.push(PR.x(x2) + "," + PR.y(-y2));
      }
    }
    var color = c > 0 ? "#1db584" : "#f87171";
    el("polyline", { points: pts1.join(" "), fill: "none", stroke: color, "stroke-width": 2 }, contourB);
    el("polyline", { points: pts2.join(" "), fill: "none", stroke: color, "stroke-width": 2 }, contourB);
  });
  var saddlePt = el("circle", { cx: PR.cx, cy: PR.cy, r: 7, fill: "#f87171", opacity: 0 }, right);
  var saddleLab = txt(right, PR.cx + 12, PR.cy + 30, "lbl lbl-r", "saddle", "start");
  show(saddleLab, false);

  // Direction arrows with values (left panel).
  var dirGroup = el("g", { opacity: 0 }, left);
  var dirTexts = [];
  [0, 45, 90, 135, 180, 225, 270, 315].forEach(function (deg) {
    var r = (deg * Math.PI) / 180;
    var ux = Math.cos(r), uy = Math.sin(r);
    var a = arrow(dirGroup, "g", 2.5);
    setLine(a, PL.x(0), PL.y(0), PL.x(ux * 2.3), PL.y(uy * 2.3));
    var t = txt(dirGroup, PL.x(ux * 3.15), PL.y(uy * 3.15) + 4, "lbl lbl-g", round1(qfA(ux, uy)), "middle");
    dirTexts.push(t);
  });
  // Negative directions (right panel).
  var dirGroupB = el("g", { opacity: 0 }, right);
  [0, 90, 180, 270].forEach(function (deg) {
    var r = (deg * Math.PI) / 180;
    var ux = Math.cos(r), uy = Math.sin(r);
    var v = qfB(ux, uy);
    var a = arrow(dirGroupB, v >= -0.01 ? "g" : "r", 2.5);
    setLine(a, PR.x(0), PR.y(0), PR.x(ux * 2.3), PR.y(uy * 2.3));
    txt(dirGroupB, PR.x(ux * 3.15), PR.y(uy * 3.15) + 4, v >= -0.01 ? "lbl lbl-g" : "lbl lbl-r", round1(v), "middle");
  });

  // Eigenvalue bars (left).
  var eig = el("g", { opacity: 0 }, left);
  var ex = el("line", { x1: PL.x(0), y1: PL.y(0), x2: PL.x(3.6), y2: PL.y(0), stroke: "#e2b44a", "stroke-width": 4, "marker-end": "url(#ah-y)" }, eig);
  var ey = el("line", { x1: PL.x(0), y1: PL.y(0), x2: PL.x(0), y2: PL.y(3.6 * 0.5), stroke: "#38bdf8", "stroke-width": 4, "marker-end": "url(#ah-b)" }, eig);
  txt(eig, PL.x(3.6) - 4, PL.y(0) - 12, "lbl lbl-y", "λ₁ = 2 > 0", "end");
  txt(eig, PL.x(0) + 10, PL.y(1.8) + 4, "lbl lbl-b", "λ₂ = 1 > 0", "start");
  var eigB = el("g", { opacity: 0 }, right);
  txt(eigB, PR.x(0) + 10, PR.y(-2.4), "lbl lbl-r", "λ₂ = −1 < 0", "start");
  txt(eigB, PR.x(3.6) - 4, PR.y(0) - 12, "lbl lbl-g", "λ₁ = 1 > 0", "end");

  var xArrow = arrow(left, "y", 3.5);
  setLine(xArrow, PL.x(0), PL.y(0), PL.x(1.5), PL.y(1.5));
  var xLab = txt(left, PL.x(1.5) + 8, PL.y(1.5) - 6, "lbl lbl-y", "x = [1, 1]", "start");
  show(xArrow, false);
  show(xLab, false);
  var note = txt(svg, 320, 338, "note", "", "middle");

  function render(index, id) {
    show(left, true);
    show(right, index >= 5);
    show(contourA, id === "bowl" || id === "eigenvalues" || id === "ml-connection" || id === "non-pd-contrast");
    show(xArrow, id === "quadratic-form");
    show(xLab, id === "quadratic-form");
    show(ball, id === "bowl" || id === "ml-connection");
    show(ballLab, id === "bowl" || id === "ml-connection");
    show(dirGroup, id === "directions" || id === "positive-values");
    show(contourB, index >= 5);
    show(dirGroupB, id === "non-pd-contrast");
    show(saddlePt, index >= 5);
    show(saddleLab, index >= 5);
    show(eig, id === "eigenvalues");
    show(eigB, id === "non-pd-contrast");
    dirTexts.forEach(function (t) { show(t, true); });
    note.textContent = "";
    if (id === "quadratic-form") note.textContent = "x = [1, 1]   →   xᵀ A x = 2·1 + 1·1 = 3";
    else if (id === "positive-values") note.textContent = "all values > 0  →  positive definite";
    else if (id === "bowl") note.textContent = "positive curvature in every direction: one stable minimum";
    else if (id === "non-pd-contrast") note.textContent = "x = [0, 1]   →   xᵀ B x = −1 (negative): not positive definite";
    else if (id === "ml-connection") note.textContent = "bowl: gradient descent settles   |   saddle: no stable minimum";
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

